import hashlib,json,os,pathlib,subprocess,sys,time
sys.path.insert(0,str(pathlib.Path.cwd()))
from scripts.bench.cpu_lease import cpu_lease
from scripts.bench.sweep_freshness import fingerprint,index_listing
from scripts.bench.groebner_measure import FAMILY
listing=index_listing(FAMILY);fp=fingerprint(listing);root=pathlib.Path('reports/bench-results')/f'hexgroebner-row-arithmetic-{fp}'
if root.with_suffix('.measurement.json').exists():raise SystemExit('retain existing observation')
root.with_suffix('.manifest').write_text(listing)
binaries={'A':pathlib.Path('/tmp/hex-groebner-branchless-before/hexgroebner_bench'),'B':pathlib.Path('.lake/build/bin/hexgroebner_bench')}
cpu,lease=cpu_lease();os.sched_setaffinity(0,{cpu})
metadata=dict(source_fingerprint=fp,baseline_source_fingerprint='7f850171b281',binary_sha256={k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in binaries.items()},cpu=cpu,affinity=sorted(os.sched_getaffinity(0)),host=os.uname().nodename,load_start=os.getloadavg(),threads=1,toolchain=pathlib.Path('lean-toolchain').read_text().strip(),c_compiler=subprocess.check_output(['cc','--version'],text=True).splitlines()[0],schedule='2 blocks AB/BA, adjacent arms; every completed sample retained',contract='p65537 grevlex, batch cap1024, identical allowances; A previous exact row arithmetic, B 32-bit Barrett where applicable and sign-mask subtraction correction; complete unchecked candidate including decode and structural basis hashing; preparation/certification/native verification/kernel checking excluded',script=pathlib.Path(__file__).read_text(),commands=[])
start=time.monotonic()
try:
 for block,order in enumerate(['AB','BA']):
  for case in ['cyclic5','cyclic6','katsura3','reimer5']:
   for arm in order:
    base=pathlib.Path(str(root)+f'-b{block}-{case}-{arm}')
    command=[str(binaries[arm]),'run','Hex.Groebner.Bench.'+case,'--repeats','3','--min-total-seconds','0.5','--export-file',str(base.with_suffix('.json'))];metadata['commands'].append(command)
    with base.with_suffix('.log').open('w') as output:result=subprocess.run(command,stdout=output,stderr=subprocess.STDOUT)
    print(base,'exit',result.returncode,flush=True)
    if result.returncode:raise SystemExit('failed arm, retained records')
finally:
 metadata.update(load_end=os.getloadavg(),elapsed_seconds=time.monotonic()-start);root.with_suffix('.measurement.json').write_text(json.dumps(metadata,indent=2)+'\n');lease.close()
